function uploadPublicationMedia(id,file,progress){return new Promise((resolve,reject)=>{const req=new XMLHttpRequest();req.open('POST','/api/announcements/'+id+'/media');req.withCredentials=true;req.setRequestHeader('X-CSRF-Token',state.csrf);req.setRequestHeader('Content-Type',file.type||'application/octet-stream');req.upload.onprogress=e=>{if(progress&&e.lengthComputable){progress.hidden=false;progress.value=Math.round(e.loaded/e.total*100)}};req.onload=()=>{let result;try{result=JSON.parse(req.responseText)}catch{result={error:'Réponse invalide.'}}if(req.status>=200&&req.status<300)resolve(result);else reject(Error(result.error||'Envoi du média échoué.'))};req.onerror=()=>reject(Error('Connexion perdue pendant l’envoi. Le brouillon reste enregistré.'));req.send(file)})}
