document.addEventListener('click',async e=>{let route=e.target.closest('[data-route]');if(route){e.preventDefault();return navigate(route.dataset.route)}let a=e.target.closest('[data-action]');if(a){if(a.classList.contains('modal-backdrop')&&e.target!==a)return;e.preventDefault();return action(a.dataset.action,a.dataset.id||'',a)}});
document.addEventListener('submit',e=>{let f=e.target.closest('form[data-form]');if(f){e.preventDefault();if(['register','password-change','reset','user-create'].includes(f.dataset.form)&&!showPasswordFeedback(f,true))return;if(!f.checkValidity()){f.reportValidity();return}let button=e.submitter;if(button){button.disabled=true;setTimeout(()=>button.disabled=false,1300)}submit(f,e)}});
async function loadRoster(){let selectCourse=$('#modal-root select[name=course_id]'),field=$('#roster-field');if(!field||!selectCourse)return;let id=selectCourse.value;if(!id){field.innerHTML='<div class="muted-note">Aucun cours attribué. Contactez le département.</div>';return}try{let d=await api('/courses/'+id+'/students');field.innerHTML=select('Étudiant','student_id',d.items.length?d.items.map(x=>[x.id,x.name+' · '+x.identifier]):[['','Aucun étudiant inscrit']]);}catch(e){field.innerHTML=`<div class="muted-note">${E(e.message)}</div>`}}
document.addEventListener('change',e=>{if(e.target.name==='content_type'){const type=e.target.value,field=$('#publication-file-field'),body=e.target.closest('form')?.querySelector('[name=body]');if(field)field.hidden=type==='text';if(body)body.required=type==='text';const file=field?.querySelector('input[type=file]');if(file){file.required=type!=='text';file.accept=type.includes('image')?'image/jpeg,image/png,image/webp':type.includes('video')?'video/mp4,video/webm':'image/jpeg,image/png,image/webp,video/mp4,video/webm';file.value='';$('#publication-preview').replaceChildren()}}if(e.target.name==='media_file'){const f=e.target.files?.[0],preview=e.target.closest('form')?.querySelector('#publication-preview');if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);if(preview){preview.replaceChildren();if(f&&(f.type.startsWith('image/')||f.type.startsWith('video/'))){state.previewUrl=URL.createObjectURL(f);const node=document.createElement(f.type.startsWith('image/')?'img':'video');node.className='publication-media';node.src=state.previewUrl;if(node.tagName==='VIDEO')node.controls=true;preview.append(node)}else if(f)preview.textContent='Format de fichier non pris en charge.'}}});
document.addEventListener('change',e=>{if(e.target.name==='level'&&e.target.closest('form[data-form=register]')){const sel=document.querySelector('form[data-form=register] select[name=track]'),cycle=e.target.value.startsWith('Licence')?'Licence':e.target.value.startsWith('Master')?'Master':'Doctorat';if(sel)sel.innerHTML='<option value="">Non précisé</option>'+(state.meta.tracks||[]).filter(t=>JSON.parse(t.levels_json||'[]').includes(cycle)).map(t=>`<option value="${E(t.name)}">${E(t.name)}</option>`).join('')}if(e.target.id==='font-px'&&$('#font-preview')){$('#font-preview').style.fontSize=e.target.value+'px';let custom=document.querySelector('form[data-form=font] input[name=custom_px]');if(custom)custom.value=''}if(e.target.id==='result-view-status'||e.target.id==='result-view-sort')$('#result-view-rows').innerHTML=resultViewRows();if(e.target.id==='view-status'||e.target.id==='view-sort')$('#view-rows').innerHTML=viewRows();if(e.target.id==='tracking-scope'){state.trackingScope=e.target.value;draw()}if(e.target.matches('select[name=course_id]'))loadRoster();if(e.target.matches('select[name=kind]')){let extra=$('#student-extra');if(extra)extra.style.display=e.target.value==='etudiant'?'contents':'none'}});
document.addEventListener('input',e=>{if(['password','password_confirm'].includes(e.target.name)&&e.target.closest('form[data-form]')?.querySelector('.password-feedback'))showPasswordFeedback(e.target.closest('form'),false)});
document.addEventListener('input',e=>{if(e.target.name==='custom_px'&&e.target.closest('form[data-form=font]')){let px=Number(e.target.value||$('#font-px')?.value||16);if(px>=14&&px<=24){$('#font-preview').style.fontSize=px+'px'}}if(e.target.id==='result-view-search'){$('#result-view-rows').innerHTML=resultViewRows()}if(e.target.id==='view-search'){let pos=e.target.selectionStart;$('#view-rows').innerHTML=viewRows();e.target.focus();e.target.setSelectionRange(pos,pos)}if(e.target.id==='tracking-search'){state.trackingFilter=e.target.value;let pos=e.target.selectionStart;draw();let input=$('#tracking-search');input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.id==='filter'){state.filter=e.target.value;let pos=e.target.selectionStart;draw();let input=$('#filter');input?.focus();input?.setSelectionRange(pos,pos)}});
function portalMatches(user){const isChef=user?.roles?.some(r=>r.name==='chef');if(isChef!==chiefPortal){location.replace((isChef?'/chef':'/')+location.hash);return false}return true}
async function openInitialRoute(){const hash=location.hash.slice(1),match=/^notifications\/(\d+)$/.exec(hash);await navigate(match?'notifications':nav.some(x=>x[0]===hash&&visibleNav(x))?hash:'dashboard');syncUnread();if(match)await action('open-notification',match[1]);}
window.addEventListener('hashchange',()=>{if(!state.me){if(location.hash.startsWith('#reset/')){state.authTab='reset';renderAuth()}return}let deep=/^notifications\/(\d+)$/.exec(location.hash.slice(1));if(deep){navigate('notifications').then(()=>action('open-notification',deep[1]));return}let r=location.hash.slice(1).split('/')[0];if(r!==state.route&&nav.some(x=>x[0]===r&&visibleNav(x)))navigate(r)});
(async()=>{try{state.meta=await api('/meta');let m=await api('/me');state.me=m.user;state.csrf=m.csrf;if(state.me){if(!portalMatches(state.me))return;try{state.data.display=await api('/display');applyTextSize(state.data.display.font_px)}catch{}await openInitialRoute();bindExistingPush()}else if(m.pending)waitForApproval(m.csrf);else renderAuth()}catch(e){$('#app').innerHTML=`<div class="empty"><strong>Connexion au serveur impossible</strong><p>${E(e.message)}</p></div>`}})();

document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(state.pending)checkApproval();if(state.me)syncUnread()}});
